import { ArrowUpRight,ArrowRight,ChevronLeft,ChevronRight,ChevronsLeft,ChevronsRight,Settings,BookOpen,History,Upload,Download,Lightbulb,RotateCcw,RefreshCw,Play,Sparkles,ShieldCheck,Check,Flag,X,LoaderCircle,Trash2,Leaf,Target,ChartNoAxesCombined,Copy } from 'lucide-react';
import Piece from './piece';
